// smoke.spec.js — tool-specific checks for Table to Markdown Converter.
// Fixtures are small fictional files generated by tests/fixtures/make-fixtures.js.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const read = (name) => fs.readFileSync(fixture(name), 'utf8');

// Dispatches a paste event carrying clipboard data, like a real paste from a spreadsheet or web page.
// Synthetic paste events have no default action, so text/plain is inserted the way the browser would.
async function paste(page, data) {
  await page.locator('#input').focus();
  await page.evaluate((d) => {
    const ta = document.getElementById('input');
    const dt = new DataTransfer();
    for (const [type, value] of Object.entries(d)) dt.setData(type, value);
    const ev = new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true });
    if (ta.dispatchEvent(ev) && d['text/plain'] != null) {
      ta.setRangeText(d['text/plain'], ta.selectionStart, ta.selectionEnd, 'end');
      ta.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }, data);
}

const outputLines = async (page) => (await page.locator('#output').inputValue()).trimEnd().split('\n');
const splitRow = (line) => line.replace(/^\|/, '').replace(/\|$/, '').split(/(?<!\\)\|/).map((c) => c.trim());

test.describe('Table to Markdown Converter', () => {
  test('empty state offers the sample link', async ({ page }) => {
    await page.goto('./');
    await expect(page.locator('#empty')).toBeVisible();
    await expect(page.locator('#output-card')).toBeHidden();
    await page.click('#load-sample-2');
    await expect(page.locator('#output-card')).toBeVisible();
    await expect(page.locator('#output')).toHaveValue(/Tidepool Cold Brew/);
  });

  test('pasting tab separated sample text produces a Markdown table with a separator row', async ({ page }) => {
    await page.goto('./');
    await paste(page, { 'text/plain': read('tidepool.tsv') });
    await expect(page.locator('#output')).toHaveValue(/\| Drink/);
    const lines = await outputLines(page);
    expect(lines).toHaveLength(7); // header, separator, five drinks
    expect(splitRow(lines[0])).toEqual(['Drink', 'Size ml', 'Price', 'Notes']);
    expect(lines[1]).toMatch(/^\|( *:?-{3,}:? *\|){4}$/);
    // pretty padding: every line has the same length, so pipes line up
    expect(new Set(lines.map((l) => l.length)).size).toBe(1);
    await expect(page.locator('#summary')).toContainText('5 rows × 4 columns');
    await expect(page.locator('#summary')).toContainText('tab separated');
    // the preview is a real table built from text
    await expect(page.locator('#preview tbody tr')).toHaveCount(5);
    await expect(page.locator('#preview thead th').nth(2)).toHaveText('Price');
    // compact mode drops the padding
    await page.uncheck('#opt-pad');
    const compact = await outputLines(page);
    expect(compact[0]).toBe('| Drink | Size ml | Price | Notes |');
    expect(compact[1]).toBe('| --- | ---: | ---: | --- |');
  });

  test('pasting an HTML table reads it through DOMParser and repeats merged cells', async ({ page }) => {
    await page.goto('./');
    const html = '<meta charset="utf-8"><table><tr><th>Drink</th><th>Price</th></tr>'
      + '<tr><td rowspan="2">Flat White</td><td>4.20</td></tr><tr><td>4.60</td></tr>'
      + '<tr><td colspan="2">Closed<br>Mondays <img src="x" onerror="window.__pwned=1"></td></tr></table>';
    await paste(page, { 'text/html': html, 'text/plain': 'Drink\tPrice' });
    await expect(page.locator('#preview tbody tr')).toHaveCount(3);
    const lines = await outputLines(page);
    expect(splitRow(lines[3])[0]).toBe('Flat White');
    expect(splitRow(lines[4])).toEqual(['Closed<br>Mondays', 'Closed<br>Mondays']);
    expect(await page.evaluate(() => window.__pwned)).toBeUndefined();
    await expect(page.locator('#preview img')).toHaveCount(0);
  });

  test('pasting CSV with quoted commas keeps those commas inside one cell', async ({ page }) => {
    await page.goto('./');
    await paste(page, { 'text/plain': read('tidepool-quoted.csv') });
    await expect(page.locator('#summary')).toContainText('comma separated');
    const lines = await outputLines(page);
    expect(splitRow(lines[2])).toEqual(['Flat White', '180', '4.20', 'Double ristretto, silky milk']);
    expect(splitRow(lines[3])).toEqual(['Cortado, iced', '120', '3.80', 'Equal parts, "half and half"']);
    await expect(page.locator('#preview tbody tr').nth(2).locator('td').nth(3)).toHaveText('Oat milk, cocoa dust, cinnamon');
  });

  test('a CSV file can be opened, and wrong file types are rejected', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [fixture('sample.png'), fixture('tidepool-quoted.csv')]);
    await expect(page.locator('#results .alert--error')).toContainText('sample.png');
    await expect(page.locator('#output')).toHaveValue(/Cortado, iced/);
    await page.setInputFiles('#file-input', fixture('sample.pdf'));
    await expect(page.locator('#results .alert--error')).toContainText('only CSV, TSV, TXT, HTML and Markdown');
  });

  test('unbalanced quotes are pointed out', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('broken-quotes.csv'));
    await expect(page.locator('#results .alert--error')).toContainText(/Unbalanced quotes/);
    await expect(page.locator('#output-card')).toBeHidden();
  });

  test('choosing right alignment for the Price column writes a colon at the right of its separator', async ({ page }) => {
    await page.goto('./');
    await page.click('#load-sample');
    await page.click('button[aria-label="Align Price left"]');
    let sep = splitRow((await outputLines(page))[1]);
    expect(sep[2]).toMatch(/^:-+$/);
    await page.click('button[aria-label="Align Price right"]');
    await expect(page.locator('button[aria-label="Align Price right"]')).toHaveAttribute('aria-pressed', 'true');
    sep = splitRow((await outputLines(page))[1]);
    expect(sep[2]).toMatch(/^-+:$/);
    expect(sep[2].startsWith(':')).toBe(false);
    // right-aligned cells are padded on the left
    expect((await outputLines(page))[2]).toContain('|  4.20 |');
    await page.click('button[aria-label="Align Notes center"]');
    expect(splitRow((await outputLines(page))[1])[3]).toMatch(/^:-+:$/);
    // Auto: numeric columns go right, text columns stay unmarked
    expect(splitRow((await outputLines(page))[1])[1]).toMatch(/^-+:$/);
    expect(splitRow((await outputLines(page))[1])[0]).toMatch(/^-+$/);
  });

  test('pipe characters inside cells are escaped in the output', async ({ page }) => {
    await page.goto('./');
    await page.click('#load-sample');
    const out = await page.locator('#output').inputValue();
    expect(out).toContain('Equal parts espresso \\| milk');
    expect(out).not.toMatch(/espresso \| milk/);
    // every row still has exactly four cells
    for (const line of await outputLines(page)) expect(splitRow(line)).toHaveLength(4);
    await expect(page.locator('#preview tbody tr').nth(1).locator('td').nth(3)).toHaveText('Equal parts espresso | milk');
    // optional escaping of backslashes and asterisks
    await page.fill('#input', 'Name\tNote\nalpha\t*bold* C:\\temp');
    await page.check('#opt-escape');
    await expect(page.locator('#output')).toHaveValue(/\\\*bold\\\* C:\\\\temp/);
  });

  test('the Copy button places the Markdown on the clipboard and shows a confirmation', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await page.goto('./');
    await page.click('#load-sample');
    const md = await page.locator('#output').inputValue();
    await page.click('#copy');
    await expect(page.locator('.toast')).toContainText('Markdown copied');
    await expect(page.locator('#copy')).toHaveText(/Copied/);
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(md);
    // keyboard shortcut copies too
    await page.evaluate(() => navigator.clipboard.writeText('cleared'));
    await page.locator('#input').focus();
    await page.keyboard.press('ControlOrMeta+Enter');
    await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe(md);
  });

  test('Download saves table.md with the Markdown', async ({ page }) => {
    await page.goto('./');
    await page.click('#load-sample');
    const md = await page.locator('#output').inputValue();
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('table.md');
    const text = fs.readFileSync(await download.path(), 'utf8');
    expect(text).toBe(md);
    expect(text.length).toBeGreaterThan(200);
    expect(text.split('\n')[1]).toMatch(/^\| -+ \|/);
  });

  test('reverse mode turns a Markdown table into CSV', async ({ page }) => {
    await page.goto('./');
    await page.click('#mode-csv');
    await expect(page.locator('#copy')).toHaveText('Copy CSV');
    await page.fill('#input', read('tidepool-table.md'));
    await expect(page.locator('#output')).toHaveValue(/^Drink,Size ml,Price,Notes\n/);
    const csv = await page.locator('#output').inputValue();
    expect(csv).toContain('Flat White,180,4.20,"Double ristretto, silky milk"');
    expect(csv).toContain('Cortado,120,"3,80",Equal parts espresso | milk');
    expect(csv).toContain('"Seasonal\nspecial"');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('table.csv');
    expect(fs.readFileSync(await download.path(), 'utf8')).toBe(csv);
    // round trip back to Markdown
    await page.click('#mode-md');
    await expect(page.locator('#output')).toHaveValue(/espresso \\\| milk/);
  });

  test('wide characters and ragged rows are padded correctly', async ({ page }) => {
    await page.goto('./');
    await page.fill('#input', 'Item,Label\n茶,Green\nCafé,Latte,Extra\n☕,');
    await expect(page.locator('#output')).toHaveValue(/Column 3/);
    const lines = await outputLines(page);
    expect(splitRow(lines[0])).toEqual(['Item', 'Label', 'Column 3']);
    expect(lines.every((l) => splitRow(l).length === 3)).toBe(true);
    // the wide character takes two columns, so its row is one space shorter in code points
    expect(lines[2].indexOf('|', 1)).toBe(lines[0].indexOf('|', 1) - 1);
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await page.click('#load-sample');
    await expect(page.locator('#output-card')).toBeVisible();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const id of ['#input', '#output', '#copy', '#download', '#load-sample']) {
      const box = await page.locator(id).boundingBox();
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width).toBeLessThanOrEqual(391);
    }
    await page.click('button[aria-label="Align Price right"]');
    expect(splitRow((await outputLines(page))[1])[2]).toMatch(/-:$/);
  });

  test('window.__demo shows a finished result', async ({ page }) => {
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#output')).toHaveValue(/Tidepool Cold Brew/);
    await expect(page.locator('#preview tbody tr')).toHaveCount(5);
  });
});
